import{_ as e,o as t,c as o,ae as d}from"./chunks/framework.Co1PSFSm.js";const h=JSON.parse('{"title":"Módulo POA","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/poa.md","filePath":"modulos/poa.md","lastUpdated":null}'),r={name:"modulos/poa.md"};function l(i,a,c,s,n,u){return t(),o("div",null,[...a[0]||(a[0]=[d('<h1 id="modulo-poa" tabindex="-1">Módulo POA <a class="header-anchor" href="#modulo-poa" aria-label="Permalink to &quot;Módulo POA&quot;">​</a></h1><h2 id="descripcion" tabindex="-1">Descripción <a class="header-anchor" href="#descripcion" aria-label="Permalink to &quot;Descripción&quot;">​</a></h2><p>El <strong>Programa Anual de Trabajo (POA)</strong> compara metas comprometidas contra ejecución real para cada concepto, por almacén o en consolidado.</p><h2 id="rutas" tabindex="-1">Rutas <a class="header-anchor" href="#rutas" aria-label="Permalink to &quot;Rutas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Propósito</th></tr></thead><tbody><tr><td>GET</td><td><code>/poa</code></td><td>Vista principal con filtros</td></tr><tr><td>GET</td><td><code>/poa/export</code></td><td>Descarga Excel o PDF</td></tr><tr><td>POST</td><td><code>/poa/nota</code></td><td>Guardar nota aclaratoria</td></tr><tr><td>POST</td><td><code>/poa/sync</code></td><td>Sincronizar desde ER</td></tr></tbody></table><h2 id="filtros" tabindex="-1">Filtros <a class="header-anchor" href="#filtros" aria-label="Permalink to &quot;Filtros&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parámetro</th><th>Valores</th><th>Default</th></tr></thead><tbody><tr><td><code>anio</code></td><td>2000-2100</td><td>Año actual</td></tr><tr><td><code>almacen_id</code></td><td>ID numérico o vacío (consolidado)</td><td>Consolidado</td></tr><tr><td><code>periodo</code></td><td><code>mensual</code>, <code>trimestral</code>, <code>anual</code></td><td><code>mensual</code></td></tr><tr><td><code>mes</code></td><td>1-12</td><td>Mes actual</td></tr><tr><td><code>trimestre</code></td><td>1-4</td><td>Según mes actual</td></tr></tbody></table><h2 id="estructura-de-la-tabla" tabindex="-1">Estructura de la Tabla <a class="header-anchor" href="#estructura-de-la-tabla" aria-label="Permalink to &quot;Estructura de la Tabla&quot;">​</a></h2><p>Cada concepto POA tiene 2 filas:</p><ul><li><strong>Fila 1</strong> (label_fila_1, ej. &quot;COMPROMETIDO&quot;): META</li><li><strong>Fila 2</strong> (label_fila_2, ej. &quot;REALIZADO&quot;): REAL</li></ul><p>Columnas: Concepto | Unidad | Meta Anual | Avance Período | % Período | % Anual | Notas</p><h2 id="casos-especiales" tabindex="-1">Casos Especiales <a class="header-anchor" href="#casos-especiales" aria-label="Permalink to &quot;Casos Especiales&quot;">​</a></h2><h3 id="conceptos-porcentaje-oportunidad-eficiencia" tabindex="-1">Conceptos Porcentaje (Oportunidad, Eficiencia) <a class="header-anchor" href="#conceptos-porcentaje-oportunidad-eficiencia" aria-label="Permalink to &quot;Conceptos Porcentaje (Oportunidad, Eficiencia)&quot;">​</a></h3><ul><li>META siempre = 100</li><li>Avance del período siempre = 100</li><li>% de logro = Real / 100</li></ul><h3 id="ventas-presupuesto-de-venta-par-pe" tabindex="-1">Ventas (Presupuesto de Venta PAR/PE) <a class="header-anchor" href="#ventas-presupuesto-de-venta-par-pe" aria-label="Permalink to &quot;Ventas (Presupuesto de Venta PAR/PE)&quot;">​</a></h3><ul><li>Las METAs vienen del ER (concepto VENTAS A TIENDAS, id=1)</li><li>Los REALes vienen de registros con programa PAR o PE y línea de producto</li></ul><h3 id="notas-aclaratorias" tabindex="-1">Notas Aclaratorias <a class="header-anchor" href="#notas-aclaratorias" aria-label="Permalink to &quot;Notas Aclaratorias&quot;">​</a></h3><ul><li>Se guardan por concepto, almacén, año y mes</li><li>Soporte para mes (1-12), trimestre (101-104) y anual (0)</li><li>Se muestran en la tabla y en exportaciones</li></ul><h2 id="exportaciones" tabindex="-1">Exportaciones <a class="header-anchor" href="#exportaciones" aria-label="Permalink to &quot;Exportaciones&quot;">​</a></h2><h3 id="excel-xlsx" tabindex="-1">Excel (.xlsx) <a class="header-anchor" href="#excel-xlsx" aria-label="Permalink to &quot;Excel (.xlsx)&quot;">​</a></h3><ul><li>Usa plantilla en <code>FORMATO POA VACIO.xlsx</code></li><li>Llena encabezados (almacén, período, tipo de avance)</li><li>Escribe 2 filas por concepto (Comprometido + Realizado)</li><li>Formato de porcentaje con 2 decimales</li></ul><h3 id="pdf" tabindex="-1">PDF <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;PDF&quot;">​</a></h3><ul><li>Renderiza vista Blade <code>poa.pdf</code> con DomPDF</li><li>Horizontal, tamaño tabloide</li><li>Mismos datos que Excel</li></ul>',23)])])}const m=e(r,[["render",l]]);export{h as __pageData,m as default};
